struct FfnCase{one::Fixture z;one::FV a,b,res;};
inline std::vector<FfnCase> ffnCases(std::vector<one::Fixture> fs){readLn1Parameters(fs);readLn1Producers(fs);std::vector<FfnCase> v;for(auto& z:fs)if(z.checkpoint&&unsigned(z.v.at("producer_k")[0])==128)v.push_back({z,z.v.at("producer_a"),z.v.at("producer_b"),z.v.at("producer_res")});require(v.size()==8);uint32_t seed=18211;for(unsigned kind=0;kind<8;++kind){auto c=v[kind];c.z.index=24+kind;for(unsigned j=0;j<c.a.size();++j){seed=1664525u*seed+1013904223u;c.a[j]=float(seed>>16)/65536.f;if(kind==1&&j%7)c.a[j]=0;if(kind==2)c.a[j]=1;if(kind==3)c.a[j]*=16;if(kind==4)c.a[j]*=1e-8f;if(kind==5)c.a[j]=.5f+(j%11)*.0001f;}for(unsigned j=0;j<c.b.size();++j){seed=1664525u*seed+1013904223u;c.b[j]=float(int(seed>>16)-32768)/65536.f;if(kind==2)c.b[j]=(j/64%2?-1:1)*.125f;if(kind==3)c.b[j]*=.01f;}v.push_back(c);}return v;}
