inline int run(const std::string& mode,const std::vector<one::Fixture>& original){unsigned bad=0;if(mode=="oneClosureA"){auto fs=upstreamreference::fullUpstream(original);bad=rawStandalone(fs);if(!bad)bad=rawChain(fs);}else if(mode=="oneClosureB"){bad=segmentstudy::projections(original);if(!bad)bad=heads(original);}else if(mode=="oneClosureC"){bad=segmentstudy::producers(original);if(!bad)bad=ffn(original);}else return 1;std::printf("summary,%s,failures=%u,cpu_fallback=0,input_mutation=0,finite=1,poison_remaining=0,canary_failures=0,training_updates=0\n",mode.c_str(),bad);return bad?4:0;}
